/**
 * Internal debug logger. Disabled by default. Enable via `setEventDebugLogging(true)`
 * to trace registration and dispatch when debugging.
 */
let debugEnabled = false;
const LOG_PREFIX = "[stylish:events]";
function dbg(message: string, meta?: Record<string, unknown>) {
  if (!debugEnabled) return;
  try {
    LOGGING: if (meta) console.debug(LOG_PREFIX, message, meta);
    else console.debug(LOG_PREFIX, message);
  } catch {
    // ignore logging errors
  }
}
/** Enables or disables debug logging for event registration/dispatch. */
export function setEventDebugLogging(enabled: boolean) {
  debugEnabled = !!enabled;
}

// Extracts the callback parameter type from an event signal's subscribe method
type EventOf<TSignal> = TSignal extends {
  subscribe(callback: (arg: infer TEvent) => void, ...rest: any[]): any;
}
  ? TEvent
  : never;

// Extracts the native filter options type from an event signal's subscribe
// method; `never` when the signal takes no options.
type SignalOptionsOf<TSignal> = TSignal extends {
  subscribe(callback: (arg: any) => void, options?: infer TOptions): any;
}
  ? unknown extends TOptions
    ? never
    : Exclude<TOptions, undefined>
  : never;

// Derived from the @minecraft/server API so payload types stay in sync
type WorldAfterEventMap = {
  [K in Extract<keyof WorldAfterEvents, string>]: EventOf<WorldAfterEvents[K]>;
};
type WorldBeforeEventMap = {
  [K in Extract<
    keyof WorldBeforeEvents,
    string
  > as `before${Capitalize<K>}`]: EventOf<WorldBeforeEvents[K]>;
};
type WorldAfterOptionsMap = {
  [K in Extract<keyof WorldAfterEvents, string>]: SignalOptionsOf<
    WorldAfterEvents[K]
  >;
};
type WorldBeforeOptionsMap = {
  [K in Extract<
    keyof WorldBeforeEvents,
    string
  > as `before${Capitalize<K>}`]: SignalOptionsOf<WorldBeforeEvents[K]>;
};

// Strongly-typed mapping between event names and their callback parameter types.
// After events use the plain signal name ("playerJoin"); before events are
// prefixed with "before" ("beforeItemUse").
export interface EventMap extends WorldAfterEventMap, WorldBeforeEventMap {
  startup: StartupEvent;
  beforeShutdown: ShutdownEvent;
  scriptEventReceive: ScriptEventCommandMessageAfterEvent;
}
// Native subscribe filter options per event; `never` when unsupported.
export interface EventOptionsMap
  extends WorldAfterOptionsMap,
    WorldBeforeOptionsMap {
  startup: never;
  beforeShutdown: never;
  scriptEventReceive: ScriptEventMessageFilterOptions;
}
type EventName = keyof EventMap;
// Handlers may be sync or async — return values (including promises) are
// ignored by the dispatcher. Typed as `=> void` so concise arrows and async
// functions are both accepted.
type Handler<E extends EventName> = (e: EventMap[E]) => void;

const registries: { [K in EventName]?: Array<Handler<K>> } =
  Object.create(null);
function getRegistry<E extends EventName>(event: E) {
  return (registries[event] ??= []) as Array<Handler<E>>;
}

// ---------------------------------------------------------------------------
// Dispatch & platform wiring
// ---------------------------------------------------------------------------

const subscribed: Partial<Record<EventName, boolean>> = {};

function makeDispatch(reg: AnyHandler[], event: string) {
  return (e: any) => {
    if (debugEnabled) dbg("dispatch", { event, count: reg.length });
    if (reg.length === 1) {
      reg[0](e);
      return;
    }
    for (let i = 0; i < reg.length; i++) reg[i](e);
  };
}

type AnySignal = {
  subscribe(callback: (e: any) => void, options?: unknown): any;
  unsubscribe?(callback: (e: any) => void): void;
};

/**
 * Resolves the platform event signal for a registry event name.
 * Returns undefined for events wired directly in `init()`.
 */
function resolveSignal(event: EventName): AnySignal | undefined {
  switch (event) {
    case "startup":
      // wired in init()
      return undefined;
    case "beforeShutdown":
      return system.beforeEvents.shutdown;
    case "scriptEventReceive":
      return system.afterEvents.scriptEventReceive;
  }
  if (event.startsWith("before")) {
    const rest = event.slice("before".length);
    const key = rest.charAt(0).toLowerCase() + rest.slice(1);
    return (world.beforeEvents as any)[key];
  }
  return (world.afterEvents as any)[event];
}

/**
 * Subscribes on the native signal, deferring one tick via system.run if the
 * call lands in restricted-execution mode (where subscribe throws but
 * system.run is allowed). Returns true when subscribed, false when deferred
 * or failed.
 */
function trySubscribe(
  signal: AnySignal,
  callback: (e: any) => void,
  options: unknown,
  label: string,
  retry: () => void,
  isRetry: boolean
): boolean {
  try {
    if (options === undefined) signal.subscribe(callback);
    else signal.subscribe(callback, options);
    return true;
  } catch (err) {
    if (!isRetry) {
      dbg("subscribeDeferred", { event: label });
      system.run(retry);
      return false;
    }
    LOGGING: console.error(`${LOG_PREFIX} failed to subscribe to '${label}':`, err);
    return false;
  }
}

function wirePlatformEvent<E extends EventName>(event: E, isRetry = false) {
  dbg("wirePlatformEvent", { event });
  if (subscribed[event]) {
    dbg("alreadyWired", { event });
    return;
  }
  const signal = resolveSignal(event);
  if (!signal) return;
  dbg("subscribe", { event });
  const ok = trySubscribe(
    signal,
    makeDispatch(getRegistry(event) as AnyHandler[], event),
    undefined,
    event,
    () => wirePlatformEvent(event, true),
    isRetry
  );
  if (ok) subscribed[event] = true;
}

function maybeWirePlatformEvents(event?: EventName) {
  dbg("maybeWirePlatformEvents", { startupTriggered: isStartupTriggered() });
  if (!isStartupTriggered()) {
    return;
  }
  if (event) {
    if (getRegistry(event).length > 0) wirePlatformEvent(event);
    return;
  }
  for (const evt of Object.keys(registries) as EventName[]) {
    if (getRegistry(evt).length > 0) wirePlatformEvent(evt);
  }
  for (const rec of filteredRecords.values()) {
    if (rec.handlers.length > 0) wireFilteredRecord(rec);
  }
  wireScriptEventRouter();
}

onStartupTriggered(() => maybeWirePlatformEvents());

// ---------------------------------------------------------------------------
// Filtered subscriptions (native subscribe options)
// ---------------------------------------------------------------------------

interface FilteredRecord {
  event: EventName;
  options: object;
  handlers: AnyHandler[];
  wired: boolean;
}

const filteredRecords = new Map<string, FilteredRecord>();
let filteredKeyCounter = 0;

/**
 * Best-effort stable key so identical filter options share one native
 * subscription. Non-serializable options (e.g. block permutations) fall back
 * to a unique key — correct, just no dedup.
 */
function filteredKey(event: EventName, options: object): string {
  try {
    return `${event}�${JSON.stringify(
      options,
      Object.keys(options).sort()
    )}`;
  } catch {
    return `${event}�#${filteredKeyCounter++}`;
  }
}

function getFilteredRecord(event: EventName, options: object): FilteredRecord {
  const key = filteredKey(event, options);
  let rec = filteredRecords.get(key);
  if (!rec) {
    rec = { event, options, handlers: [], wired: false };
    filteredRecords.set(key, rec);
  }
  return rec;
}

function wireFilteredRecord(rec: FilteredRecord, isRetry = false) {
  if (rec.wired || !isStartupTriggered()) return;
  const signal = resolveSignal(rec.event);
  if (!signal) return;
  dbg("subscribeFiltered", { event: rec.event });
  const ok = trySubscribe(
    signal,
    makeDispatch(rec.handlers, rec.event),
    rec.options,
    rec.event,
    () => wireFilteredRecord(rec, true),
    isRetry
  );
  if (ok) rec.wired = true;
}

// ---------------------------------------------------------------------------
// Event decorators
// ---------------------------------------------------------------------------

/**
 * An event decorator usable three ways:
 * 1. As a method decorator on static or instance methods.
 * 2. As a direct function call to register a standalone function.
 * 3. Called with native filter options (for events that support them) to get
 *    a decorator whose subscription filters in native code:
 *    `@OnEntityHurt({ entityTypes: ["wiki:boss"] })`
 */
// Note: The method-decorator overload intentionally uses a permissive function
// type to avoid cross-package type incompatibilities when consumers have a
// different @minecraft/server instance. The direct function registration keeps
// strong typing with our local EventMap.
export type EventDecorator<E extends EventName> = ((fn: Handler<E>) => void) &
  ((target: any, propertyKey: string | symbol, descriptor: any) => any) &
  ([EventOptionsMap[E]] extends [never]
    ? unknown
    : (options: EventOptionsMap[E]) => EventDecorator<E>);

export function createEventDecorator<E extends EventName>(
  event: E
): EventDecorator<E> {
  const base = makeDecorator((fn) => {
    dbg("register", { event });
    getRegistry(event).push(fn as Handler<E>);
    maybeWirePlatformEvents(event);
  });
  const impl = function EventDecorator(
    target: any,
    propertyKey?: string | symbol,
    descriptor?: any
  ): any {
    // Options factory: OnX({ ...nativeFilterOptions })
    if (
      propertyKey === undefined &&
      descriptor === undefined &&
      typeof target === "object" &&
      target !== null
    ) {
      const rec = getFilteredRecord(event, target as object);
      return makeDecorator((fn) => {
        dbg("register:filtered", { event });
        rec.handlers.push(fn);
        wireFilteredRecord(rec);
      });
    }
    return base(target, propertyKey as any, descriptor);
  };
  return impl as EventDecorator<E>;
}

