// ---------------------------------------------------------------------------
// Script event routing
// ---------------------------------------------------------------------------

type ScriptEventHandler = (e: ScriptEventCommandMessageAfterEvent) => void;

const scriptEventRoutes = new Map<string, AnyHandler[]>();
let scriptRouterToken: ((e: any) => void) | undefined;
let scriptRouterNamespaceCount = 0;

function routeScriptEvent(e: ScriptEventCommandMessageAfterEvent) {
  const list = scriptEventRoutes.get(e.id);
  if (!list) return;
  if (debugEnabled) dbg("dispatch:scriptEvent", { id: e.id, count: list.length });
  if (list.length === 1) {
    list[0](e);
    return;
  }
  for (let i = 0; i < list.length; i++) list[i](e);
}

function scriptRouterNamespaces(): string[] {
  const namespaces = new Set<string>();
  for (const id of scriptEventRoutes.keys()) {
    const colon = id.indexOf(":");
    namespaces.add(colon === -1 ? id : id.slice(0, colon));
  }
  return [...namespaces];
}

function wireScriptEventRouter(isRetry = false) {
  if (!isStartupTriggered() || scriptEventRoutes.size === 0) return;
  const namespaces = scriptRouterNamespaces();
  // Already wired and no new namespace since — nothing to do.
  if (scriptRouterToken && namespaces.length === scriptRouterNamespaceCount) {
    return;
  }
  const signal = system.afterEvents.scriptEventReceive;
  try {
    // Re-subscribe with the widened namespace filter.
    if (scriptRouterToken) signal.unsubscribe(scriptRouterToken);
    scriptRouterToken = signal.subscribe(routeScriptEvent, { namespaces });
    scriptRouterNamespaceCount = namespaces.length;
    dbg("subscribe:scriptRouter", { namespaces: namespaces.join(",") });
  } catch (err) {
    if (!isRetry) {
      dbg("subscribeDeferred", { event: "scriptEventRouter" });
      system.run(() => wireScriptEventRouter(true));
      return;
    }
    LOGGING: console.error(`${LOG_PREFIX} failed to subscribe script event router:`, err);
  }
}

/**
 * Decorator factory – routes `/scriptevent <id> <message>` commands with the
 * given id to the decorated method/function. All routes share a single native
 * subscription, filtered natively to the registered namespaces and dispatched
 * by exact id via a map lookup.
 *
 * ```ts
 * @ScriptEvent("wiki:spawn_boss")
 * static spawnBoss(e: ScriptEventCommandMessageAfterEvent) { ... }
 * ```
 */
export function ScriptEvent(id: string) {
  return makeDecorator((fn) => {
    let list = scriptEventRoutes.get(id);
    if (!list) {
      list = [];
      scriptEventRoutes.set(id, list);
    }
    list.push(fn);
    wireScriptEventRouter();
  }) as ((fn: ScriptEventHandler) => void) &
    ((target: any, propertyKey: string | symbol, descriptor: any) => any);
}

// ---------------------------------------------------------------------------
// Startup
// ---------------------------------------------------------------------------

/**
 * Invokes OnStartup event handlers.
 */
export function triggerStartupEvent(e: StartupEvent) {
  // Wire any platform events/timers that have pending handlers
  markStartupTriggered();
  const reg = getRegistry("startup");
  dbg("triggerStartupEvent", { count: reg.length });
  for (const fn of reg) {
    try {
      fn(e);
    } catch (err) {
      LOGGING: console.error("Error in startup handler:", err);
    }
  }
}
